mapper.select:
select c.id as content_id,
       coalesce(c.publish_time, 0) as publish_time
from content_items c
where c.status = 'published'
  and c.visibility = 'public'
  and exists (
      select 1
      from follows f
      join users author on author.id = f.following_id
      left join user_social_stats social on social.user_id = author.id
      where f.follower_id = #{userId}
        and f.following_id = c.author_user_id
        and f.muted = false
        and (
            exists (
                select 1
                from user_feed_entries feed_entry
                where feed_entry.user_id = f.follower_id
                  and feed_entry.content_id = c.id
            )
            or author.fanout_mode = 'pull'
            or (
                author.fanout_mode = 'auto'
                and coalesce(social.follower_count, 0) > #{fanoutOnWriteMaxFollowers}
            )
        )
  )

  and (
      coalesce(c.publish_time, 0) < #{cursorSortValue}
      or (
          coalesce(c.publish_time, 0) = #{cursorSortValue}
          and c.id < #{cursorId}
      )
  )

order by coalesce(c.publish_time, 0) desc, c.id desc
limit #{limit}

select count(*)
from users
where id = #{userId}
